-- One-time import of the existing news from the SVÖ OG 125 homepage (og = 125).
-- Skipped if og 125 already has news, so it is safe to rerun.
begin;

insert into public.news (og, date, title, content)
select 125, v.date::date, v.title, v.content
from (values
    ('2018-12-09', 'Fotos vom 3. Funturnier', 'In der Galerie findet ihr die Fotos von unserem 3. Oggauer Funturnier. Mit 24 Teilnehmern war es wieder ein voller Erfolg. Noch einmal ein Dankeschön an Johanna Wurm für die tolle Organisation sowie an alle freiwilligen Helfer und Teilnehmer.'),
    ('2019-02-17', 'Neuer Vorstand', 'Bei der diesjährigen Jahreshauptversammlung wurde bei den Neuwahlen ein neuer Vorstand gewählt. Wir wünschen diesem viel Glück bei dessen kommenden Aufgaben. Informationen zum neuen Vorstand findet ihr bei Kontakt. Bedanken möchten wir uns beim vorigen Vorstand für seine langjährige Tätigkeit.﻿'),
    ('2019-02-17', 'Beginn Frühjahrskurs', 'Der Frühjahrskurs startet dieses Jahr am Samstag, 02. März um 15:00. Danach beginnen alle Kurse Samstags immer um 16:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter Kurse﻿.﻿'),
    ('2019-02-24', 'Fotos vom Herbstkurs', 'Spät aber doch findet ihr Fotos vom Herbstkurs 2018 in der Galerie.'),
    ('2019-03-10', 'Ernährungsvortrag', 'Heimtierbedarf Bernhard Ziz bietet für Hundeschulen den Ernährungsvortrag „Worauf ist bei Hundefutter zu achten – welche Möglichkeiten gibt es“ an. Eine Anfrage wegen eines Termins wäre erst bei 12-15 Teilnehmern sinnvoll. Bei Interesse bitte per E-Mail oder in der Kantine melden.'),
    ('2019-03-05', 'Fotos vom Frühjahrskurs', 'Die ersten Fotos des Frühjahrskurses 2019 gibt es bereits in der Galerie.'),
    ('2019-05-04', 'Fotos vom Hundewandertag', 'Die Fotos unseres traditionellen Hundewandertages findet ihr in der Galerie. Danke noch einmal an alle Helfer und Teilnehmer.'),
    ('2019-05-08', '01. Juni nur Welpenkurs', 'Bitte beachten, am Samstag, 01. Juni findet nur der Welpenkurs statt. Grund ist die Hochzeit von unserem Obmann Thomas Unger und unserem Kassier Stv. Verena Siess.'),
    ('2019-06-13', 'Änderung Kurszeiten', 'Bitte beachten, auf Grund der Hitze starten die Kurse am Samstag, 15. Juni und am Samstag, 22. Juni erst um 18:00. Der Abschluss des Welpenkurses startet ebenfalls erst um 18:00 (siehe Events).'),
    ('2019-06-19', 'Fotos und Ergebnisse der OG Prüfung', 'Am Sonntag, 09. Juni fand unsere OG Prüfung bei strahlendem Sonnenschein und extrem warmen Temperaturen statt. Alle 16 Teilnehmer haben bestanden und somit durften wir die weisse Fahne hissen. Die Ergebnisse findet ihr bei den Downloads und die Fotos in der Galerie. Ein Dankeschön an unseren Richter Herrn Josef Pfeffer und unseren Prüfungsleiter Thomas Unger, sowie an alle freiwilligen Helfer und Teilnehmer.'),
    ('2019-06-24', 'Startzeit Fun-Turnier und Sommerpause', 'Auf Grund der angesagten Temperaturen haben wir den Start des Fun-Turniers vorverlegt. Beginn ist am Samstag, 29. Juni bereits um 09:00. Dies ist unsere letzte Veranstaltung vor der Sommerpause. Somit findet auch nachmittags kein Kurs mehr statt.'),
    ('2019-07-02', 'Fotos vom Fun-Turnier', 'In der Galerie findet ihr die Fotos von unserem Fun-Turnier, welches am 29. Juni stattfand. Trotz Hitze durften wir 24 Teilnehmer begrüßen. Das Starterfeld war wieder weit gefächert, von ca. 5-50kg und 5 Monaten bis fast 14 Jahren und natürlich waren die unterschiedlichste Rassen vertreten. Hier konnte wirklich jeder mitmachen. Dieses Mal ein Dankeschön an Thomas Wolf für den Parcour und natürlich an alle freiwilligen Helfer, Teilnehmer und Zuseher.'),
    ('2019-08-28', 'Beginn Herbstkurs', 'Der Herbstkurs startet dieses Jahr am Samstag, 07. September um 15:00. Danach beginnen alle Kurse Samstags immer um 16:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter Kurse﻿.﻿'),
    ('2019-09-07', 'Gratulation an neuen Kursleiter', 'Wir gratulieren Thomas Wolf zu seiner bestandenen Kursleiter 1 und 2 Prüfung. Er wird uns zukünftig vor allem bei den Welpen unterstützen. Aber natürlich auch bei den älteren, sollte mal Not am Mann sein.'),
    ('2019-09-07', 'Neu! Kalender', 'Neu auf unserer Homepage ist der Kalender. Hier findet ihr vor allem Informationen, wann bei welchem Trainer ein Kurs stattfindet. Auch falls mal einer ausfallen sollte, findet ihr diese Information im Kalender.'),
    ('2019-10-10', 'Fotos und Ergebnisse vom ASVÖ B/C Turnier', 'Am Samstag, 05. Oktober fand bei uns das ASVÖ B/C Turnier bei sehr regnerischem Wetter statt. Bedanken möchten wir uns bei unserem Richter Ernst Denk, sowie unseren Prüfungsleiter Thomas Unger. Ebenfalls ein Danke an alle Teilnehmer, besonders an unsere Gaststarter und natürlich an alle freiwilligen Helfer. Die Ergebnisse findet ihr bei den Downloads und die Fotos in der Galerie.'),
    ('2019-10-12', 'Kurse ab Heute in Donnerskirchen', 'Nach einer stressigen Woche mit Abriss in Oggau und Aufbau in Donnerskirchen haben wir es dennoch geschafft, und dürfen euch ab diesen Samstag, 12. Oktober in Donnerskirchen begrüßen. Ein großes Dankeschön an alle Helfer. Anfahrt und Geländeplan beim Kontakt.'),
    ('2019-12-02', 'Winterpause', 'Zur Zeit befinden wir uns in der Winterpause. Die OG wünscht Frohe Feiertage und ab März startet wieder unser Frühjahrskurs.'),
    ('2019-12-02', 'Fotos vom Fun-Turnier', 'In der Galerie findet ihr die Fotos von unserem Fun-Turnier, welches am 30. November stattfand. Bei sonnigem Wetter aber Kälte ging unsere letzte Veranstaltung für das Jahr 2019 mit 26 Teilnehmern zu Ende. Das Starterfeld war wieder weit gefächert. Hier konnte wirklich jeder mitmachen. Wieder ein Dankeschön an Thomas Wolf für den Parkour und natürlich an alle freiwilligen Helfer, Teilnehmer und Zuseher.'),
    ('2019-02-11', 'Beginn Frühjahrskurs', 'Der Frühjahrskurs startet dieses Jahr am Samstag, 07. März um 16:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter Kurse﻿.﻿'),
    ('2020-02-17', 'Neu! Rally Obedience', 'Unser Kursangebot wurde um Rally Obedience erweitert. Genauere Informationen hierzu bzw. zu den Kurszeiten und Kosten findet ihr bei den Kursen.'),
    ('2020-03-14', 'Achtung! Kein Kursbetrieb', 'Auf Grund der rasanten Ausbreitung des Coronavirus, sowie der Empfehlung der Regierung die sozialen Kontakte so gering wie möglich zu halten, finden ab nächster Woche keine Kurse mehr statt. Heute gibt es noch die Möglichkeit das Training zu besuchen. So bald es wieder möglich ist, werden wir den Kursbetrieb wieder aufnehmen. Wann das sein wird, erfahrt ihr natürlich hier. Wir hoffen auf euer Verständnis.'),
    ('2020-04-17', 'Hundewandertag abgesagt!', 'Leider müssen wir unseren heurigen Hundewandertag am 01. Mai auf Grund der Coronapandemie absagen. Ob wir die nächsten Veranstaltungen abhalten können, wird sich leider erst zeigen.'),
    ('2020-04-29', 'Kursbetrieb ab 02. Mai', 'Wir können unseren Kursbetrieb mit Samstag, 02. Mai wieder starten. Genauere Informationen findet ihr oberhalb im Abschnitt ''CORONAVIRUS''.'),
    ('2020-05-28', 'Kurszeiten am 30. Mai', 'Ausnahmsweise starten am Samstag, 30. Mai der Welpenkurs mit Thomas Wolf bereits um 08:30 bzw. Rally Obedience um 10:00. Begleithunde und Welpen mit Joachim beginnen, wie gewohnt, um 16:00. Genaueres siehe Kalender.'),
    ('2020-05-28', 'Update Coronavirus', 'Auf Grund von weiteren Lockerungen wird die Anzahl der Personen auf Veranstaltungen ab 29. Mai auf 100 erhöht. Darum sind ab diesem Zeitpunkt auch wieder Begleitpersonen bzw. Zuseher herzlich willkommen. Genauere Informationen findet ihr oberhalb im Abschnitt ''CORONAVIRUS''.'),
    ('2020-06-01', 'Veranstaltungen', 'Auf Grund der aktuellen Lage können der Welpenabschluss und das Fun-Turnier statt finden. Natürlich sind auch hier die Hygienemaßnahmen einzuhalten. Nähere Informationen findet ihr bei den Veranstaltungen bzw. im Abschnitt ''CORONAVIRUS''.'),
    ('2020-06-28', 'Fotos vom Fun-Turnier', 'In der Galerie findet ihr die ersten Fotos von unserem Fun-Turnier, welches am 27. Juni stattfand. Bei Traumwetter durften wir 35 Starter begrüßen. Dies ist neuer Teilnehmerrekord. Ebenfalls gab es erstmals eine eigene Kinderwertung. Das Starterfeld war wieder weit gefächert, von klein bis groß, von jung bis alt und natürlich waren die unterschiedlichste Rassen vertreten. Dieses Mal ein Dankeschön an Thomas Wolf für den Parcours und natürlich an alle freiwilligen Helfer, Teilnehmer und Zuseher.'),
    ('2020-06-28', 'Sommerpause', 'Zur Zeit befinden wir uns in der Sommerpause. Die OG wünscht einen schönen Sommer und ab September startet wieder unser Herbstkurs, sofern es die aktuelle Lage zulässt.'),
    ('2020-08-09', 'Beginn Herbstkurs', 'Der Herbstkurs startet dieses Jahr am Samstag, 05. September um 16:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter Kurse﻿.﻿'),
    ('2020-09-06', 'Aufnäher mit Vereinslogo', 'Ab sofort kann jeder, der möchte, Aufnäher mit dem neuen Vereinslogo erwerben. Die Aufnäher kosten 5,30 Euro pro Stück und sind in der Kantine erhältlich.﻿'),
    ('2020-09-06', 'Kursanmeldung jetzt online', 'Bei den Downloads findet ihr nun auch die Kursanmeldung. Diese kann direkt online ausgefüllt und dann per E-Mail (mail@og125.at) geschickt werden. Natürlich liegen die Kursanmeldungen nach wie vor in der Kantine auf bzw. können dort abgegeben werden.'),
    ('2020-09-17', 'Feedbackbogen', 'Neu bei den Downloads ist unser Feedbackbogen. Man kann ihn entweder direkt per E-Mail (mail@og125.at) schicken oder es besteht auch die Möglichkeit den Feedbackbogen anonym in der Kantine abzugeben bzw. auszufüllen. Wir freuen uns auf eure Rückmeldung. Nur dadurch können wir unser Angebot immer weiter verbessern.'),
    ('2020-09-20', 'Neue Zeiten für Welpenkurs', 'Da wir heuer so viele Welpen bei uns begrüßen dürfen, wird der Welpenkurs auf mehrere Gruppen aufgeteilt. Genaueres findest du im Kalender.'),
    ('2020-09-23', 'Heute kein Welpenkurs!', 'Es entfällt der Welpenkurs, da unser Trainer Thomas Wolf heute leider keine Zeit hat.'),
    ('2020-10-20', 'Neue Corona-Maßnahmen', 'Ab Freitag, 23. Oktober werden die Corona-Maßnahmen wieder verschärft. Dies trifft auch unseren Kursbetrieb. Genauere Informationen findet ihr oberhalb im Abschnitt ''CORONAVIRUS''.'),
    ('2020-10-20', 'Absage von Veranstaltungen', 'Auf Grund der verschärften Corona-Maßnahmen müssen wir leider fast alle geplanten Veranstaltungen (Vereinsprüfung, Fun-Turnier) absagen bzw. verschieben. Lediglich der Welpenabschluss kann voraussichtlich statt finden. Genaueres bei den ''EVENTS''.'),
    ('2020-11-04', 'Kein Kursbetrieb möglich', 'Nach Rücksprache mit der zuständigen BH, müssen wir leider unseren Herbstkurs frühzeitig beenden. Ab sofort findet kein Kursbetrieb mehr statt. Dh dass auch der Welpenabschluss abgesagt ist. Bereits bezahlte Kursgebühren werden euch für den nächsten Kurs gutgeschrieben. Dieser kann hoffentlich wieder ab März stattfinden.'),
    ('2021-01-19', 'Jahreshauptversammlung', 'Laut Statuten des SVÖ ist die Jahreshauptversammlung in den ersten beiden Monaten des Jahres abzuhalten. Auf Grund der aktuellen Lage und da keine Neuwahlen anstehen hat die Bundesleitung des SVÖ beschlossen, diese Frist bis zum 30. Juni 2021 zu verlängern. So bald das Datum für die Jahreshauptversammlung feststeht, werden natürliche alle OG Mitglieder informiert.'),
    ('2021-02-25', 'Einzeltraining möglich', 'Wie es zur Zeit aussieht, werden wir leider Anfang März nicht mit unserem Frühjahrskurs starten können. Jedoch wird es die Möglichkeit zu einem Einzeltraining geben. Genauere Informationen findet ihr oberhalb im Abschnitt ''CORONAVIRUS''.'),
    ('2021-03-27', 'Nächsten Samstag kein Training', 'Nächsten Samstag, 03. April finden auf Grund der Ausgangssperren bzw. der ''Osterruhe'' keine Trainings statt. Wie es danach weitergeht, ob Einzel- oder Gruppentraining (was laut neuester Verordnung mit Einschränkungen möglich wäre), lassen wir euch so bald wie möglich wissen.'),
    ('2021-04-06', 'Kein Training im Lockdown möglich', 'Leider können wir mit unserem Kursbetrieb bzw. dem Einzeltraining erst wieder beginnen, sobald der Lockdown zu Ende ist.'),
    ('2021-04-14', 'Kursbetrieb ab 24. April', 'Da der Lockdown im Burgenland nach dem 18. April endet, können wir ab Samstag, 24. April wieder mit unserem Kursbetrieb starten. Genauere Informationen findet ihr oberhalb im Abschnitt ''CORONAVIRUS''.'),
    ('2021-05-22', 'Eintrittstests', 'Leider bringt uns die aktuelle Verordnung vom 19. Mai wieder Verschärfungen (zB Eintrittstests). Genauere Informationen findet ihr oberhalb im Abschnitt ''CORONAVIRUS''.'),
    ('2021-06-27', 'Sommerpause', 'Bei herrlichem Wetter haben wir gestern unseren Frühjahrskurs beendet. Anfang September können wir dann hoffentlich wieder mit unserem Herbstkurs starten. Bis dahin wünschen wir allen einen schönen Sommer.'),
    ('2021-08-16', 'Beginn Herbstkurs', 'Am Samstag, 04. September starten wir wieder mit unserem Herbstkurs unter Einhaltung der 3G Regel. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen findet ihr im Kalender bzw. unter Kurse.﻿'),
    ('2021-10-31', 'Samstag nur Welpenkurs', 'Auf Grund der Vereinsprüfung findet am Samstag, 06. November nachmittags nur der Welpenkurs statt.﻿'),
    ('2019-11-10', 'Fotos und Ergebnisse der Vereinsprüfung', 'Am Sonntag, 06. November fand unsere OG Prüfung bei strahlendem Sonnenschein statt. Die Ergebnisse findet ihr bei den Downloads und die Fotos in der Galerie. Ein Dankeschön an unseren Richter Herrn Ernst Denk und unseren Prüfungsleiter Thomas Wolf, sowie an alle freiwilligen Helfer und Teilnehmer. Zusätzlich möchten wir unserer Sabine zum SVÖ Hundeführersportabzeichen in Bronze gratulieren.'),
    ('2021-11-11', '2G Regel', 'Laut aktueller Verordnung vom 10. November müssen alle Personen beim Betreten des Geländes einen 2G Nachweis (Geimpft oder Genesen) besitzen. Wir hoffen auf euer Verständnis. Offene Einheiten verfallen nicht und können natürlich auch im nächsten Jahr eingelöst werden.'),
    ('2021-11-11', 'Veranstaltungen und Winterpause', 'Auf Grund der aktuellen Situation werden wir alle geplanten Veranstaltungen (Welpenabschluss, Fun-Turnier) auf nächstes Jahr verschieben. Somit ist unser letzter Kurstag am Samstag, 27. November. Wir hoffen, dass wir im Frühjahr wieder mit unseren Kursen starten können.'),
    ('2021-11-20', 'Lockdown', 'Da es ab Montag, 22. November wieder zu einem Lockdown kommt, ist heute Samstag, 20. November der letzte Kurstag. Bleibt gesund und hoffentlich sehen wir uns im Frühjahr.'),
    ('2022-02-27', 'Corona Maßnahmen', 'Da mit 05. März fast alle Corona Maßnahmen fallen, gibt es auch bei uns keine 3G/2G Regel bzw. Maskenpflicht mehr. Jedoch wird der Verein weiterhin Desinfektionsmittel zur Verfügung stellen und bittet auch darum weiterhin Abstand einzuhalten.'),
    ('2022-02-27', 'Beginn Frühjahrskurs', 'Der Frühjahrskurs startet dieses Jahr am Samstag, 05. März um 15:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter Kurse﻿.﻿'),
    ('2022-03-30', 'Welpenkurs am Freitag, kein Kurs am Samstag', 'Der Welpenkurs findet diese Woche am Freitag, 01. April um 15:00 statt. Da auch wir nicht von Corona verschont blieben, fällt der Begleithundekurs diesen Samstag, 02. April leider aus.'),
    ('2022-04-03', 'Welpenkurs ist voll', 'Um allen unseren Teilnehmern weiters die gleiche Qualität bieten zu können, müssen wir euch leider mitteilen, dass wir zur Zeit im Welpenkurs leider keine freien Plätze mehr haben.'),
    ('2022-05-11', 'Neue Veranstaltungen', 'Wir freuen uns, dass wir endlich wieder Events veranstalten dürfen, wie Fun-Turnier, Welpenabschluss und Vereinsprüfung. Genauere Informationen findet ihr bei den EVENTS bzw. im KALENDER.'),
    ('2022-05-24', 'Kurskarten elektronisch', 'Seit Kurzem gibt es alle neu ausgestellten Kurskarten elektronisch, dh es gibt keine Kurskarten im Papierformat mehr. Wenn ihr euch einen 10er Block kauft, dann werden die offenen Einheiten bei uns im System hinterlegt bzw. abgebucht bei Verbrauch. Somit entsteht für euch kein Aufwand mehr.'),
    ('2022-06-22', 'Fotos vom Fun-Turnier', 'Bei herrlichem Wetter fand vorigen Samstag unser Fun-Turnier statt. Ein Dankeschön an alle Helfer und Teilnehmer. Die Bilder findet ihr bei den FOTOS.'),
    ('2022-06-22', 'Sommerpause', 'Am 02. Juli schließen wir unseren Frühjahrskurs mit unserer Vereinsprüfung ab. An diesem Tag ist kein Kurs mehr. Danach gehen wir in die Sommerpause. Ab September freuen wir uns dann wieder auf viele alte und neue Gesichter.'),
    ('2022-07-16', 'Gratulation', 'Wir gratulieren Petra Wolf und Claudia Pusterhofer recht herzlich zu ihrer bestandenen Kursleiter 1 und 2 Prüfung.'),
    ('2022-07-16', 'Fotos und Ergebnisse der Vereinsprüfung', 'Am Samstag, 02. Juli fand unsere OG Prüfung bei strahlendem Sonnenschein statt. Die Ergebnisse findet ihr bei den Downloads und die Fotos in der Galerie. Ein Dankeschön an unsere Richterin Katharina Kribernegg und unseren Prüfungsleiter Christian Kornfeld, sowie an alle freiwilligen Helfer und Teilnehmer.'),
    ('2022-08-26', 'Beginn Herbstkurs', 'Der Herbstkurs startet dieses Jahr am Samstag, 03. September um 15:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter Kurse﻿.﻿'),
    ('2022-10-14', 'Diesen Samstag kein Welpenkurs', 'Am Samstag, 15. Oktober entfällt der Welpenkurs, da sich unsere Trainer auf Fortbildung befinden. Der Begleithundekurs findet ganz normal statt.﻿'),
    ('2022-10-29', 'Fun-Turnier und Welpenabschluss', 'Am Samstag, 12. November ab 09 Uhr startet unser Fun-Turnier. An diesem Tag findet am Nachmittag kein Kurs statt. Der Welpenabschluss findet am Samstag, 26. November im Zuge des Welpenkurses statt. Genauere Informationen findet ihr bei den EVENTS bzw. im KALENDER.'),
    ('2022-12-01', 'Fotos vom Fun-Turnier', 'Bei herrlichem Wetter fand am Samstag, 12. November unser Fun-Turnier statt. Ein Dankeschön an alle Helfer und Teilnehmer. Die Bilder findet ihr bei den FOTOS.'),
    ('2022-12-01', 'Winterpause', 'Zur Zeit befinden wir uns in der Winterpause. Die OG wünscht Frohe Feiertage und ab März startet wieder unser Frühjahrskurs.'),
    ('2023-01-15', 'Beginn Frühjahrskurs', 'Der Frühjahrskurs startet dieses Jahr am Samstag, 04. März um 15:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter Kurse﻿.﻿'),
    ('2023-04-22', 'Neue Termine', 'Bei den EVENTS findet ihr alle Informationen zu unsere aktuellen Veranstaltungen, wie zB den Welpenabschluss am 17. Juni, unsere Vereinsprüfung am 18. Juni und das Fun-Turnier am 01.Juli.﻿'),
    ('2023-04-22', 'Kein Kurs am 24. Juni', 'Am Samstag, 24. Juni finden keine Kurse statt.'),
    ('2023-05-05', 'Neue Fotos', 'Bei den FOTOS findet ihr nun Bilder von unserem Erste Hilfe Kurs sowie von unseren Welpen bei einem Besuch am Bauernhof.'),
    ('2023-07-20', 'Neue Fotos', 'Alle Bilder von unserer Vereinsprüfung sowie vom Fun-Turnier findet ihr ab sofort bei den FOTOS. Ein Dankeschön an unseren Richter Karl Rössler sowie an alle Helfer und Teilnehmer.'),
    ('2023-08-31', 'Beginn Herbstkurs', 'Der Herbstkurs startet dieses Jahr am Samstag, 02. September ab 15:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter KURSE bzw. beim KALENDER﻿.﻿'),
    ('2023-10-06', 'Morgen Welpenkurs in Eisenstadt', 'Für ein Alltagstraining wird der Welpenkurs morgen in Eisenstadt stattfinden. Treffpunkt ist um 15:00 beim Schlosspark.'),
    ('2023-10-29', 'Fun-Turnier und Welpenabschluss', 'Der Welpenabschluss findet am Samstag, 11. November im Zuge des Welpenkurses statt. Am Samstag, 25. November ab 09:00 startet unser Fun-Turnier. An diesem Tag findet am Nachmittag kein Kurs statt. Genauere Informationen findet ihr bei den EVENTS bzw. im KALENDER.'),
    ('2024-01-14', 'Fotos vom Fun-Turnier', 'Bei den FOTOS findet ihr nun die Bilder von unserem Fun-Turnier, welches am 25. November statt fand. Ein Dankeschön an alle Helfer und Teilnehmer.'),
    ('2024-01-14', 'Beginn Frühjahrskurs', 'Der Frühjahrskurs startet dieses Jahr am Samstag, 02. März um 15:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter KURSE.'),
    ('2024-03-09', 'Celtic Warrior am 23. März', 'Am Samstag, 23. März findet der Celtic Warrior in Donnerskirchen statt. Der Zieleinlauf führt über einen Teil des OG Geländes. Ebenfalls befindet sich am unteren Sportplatz der Start- und Zielbereich. Es gibt aber ganz normalen Kursbetrieb. Es kann jedoch sein, dass etwas weiter weg geparkt werden muss bzw. dass der Zielbereich des Celtic Warriors noch gut besucht ist.'),
    ('2024-03-19', 'Gratulation an Nora und Zera', 'Nora Friedle hat am 17. März mit ihrer Zera den hervorragenden 2. Platz beim ''ÖGV Wien-Heustadlwasser Rally Obedience Wintercup'' belegt. Mit 98 Punkten in der Prüfungsstufe ROB 1 waren sie nur knapp hinter dem Erstplatzierten. Wir gratulieren zu dieser tollen Leistung.'),
    ('2024-03-19', 'Kein Welpenkurs und Begleithundekurs', 'Am Samstag, 23. März findet nur der Begleithundekurs statt (kein Welpenkurs). Dafür findet am Samstag, 30. März (Karsamstag) nur der Welpenkurs statt (kein Begleithundekurs). Einen genauen Überblick findet ihr im KALENDER.'),
    ('2024-04-19', 'Welpenkurs auf Vielfalt Farm', 'Am Samstag, 27. März findet der Welpenkurs bereits um 09:00 auf der Vielfalt Farm in Loretto statt.'),
    ('2024-05-09', 'Neue Fotos', 'Bei den FOTOS findet ihr ab sofort neue Bilder von Rally Obedience sowie vom Besuch unserer Welpen auf der Vielfalt Farm.'),
    ('2024-05-09', 'Kein Kurs am 25. Mai', 'Auf Grund der Vereinsprüfung findet am Samstag, 25 Mai findet kein Kurs statt. Zu beachten für alle Teilnehmer, Anmeldeschluss für die Prüfung ist Samstag, 18. Mai. Weitere Informationen findet ihr bei den EVENTS. Zuseher sind auch herzlich willkommen.'),
    ('2024-06-08', 'Am 15. Juni nur Welpenkurs', 'Nächsten Samstag, 15. Juni, findet kein Begleithundekurs statt. Es findet nur der Welpenkurs um 15:00 statt.'),
    ('2024-06-08', 'Fun-Turnier und Welpenabschluss', 'Der Welpenabschluss findet am Samstag, 22. Juni im Zuge des Welpenkurses statt. Am Samstag, 29. Juni ab 09:00 startet unser Fun-Turnier. An diesem Tag findet am Nachmittag kein Kurs statt. Genauere Informationen findet ihr bei den EVENTS bzw. im KALENDER. Das Fun-Turnier ist die letzte Veranstaltung vor der Sommerpause.'),
    ('2024-08-24', 'Beginn Herbstkurs', 'Der Herbstkurs startet dieses Jahr am Samstag, 07. September um 15:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter KURSE.'),
    ('2024-09-13', 'Neue Zeiten für Welpenkurs', 'Der Welpenkurs startet ab sofort Samstags schon um 09:00. Die Zeiten für den Begleithundekurs bleiben bei 15:00 für Anfänger und 16:30 für Fortgeschrittene. Die aktuellen Zeiten findest du im KALENDER.'),
    ('2024-09-13', 'Morgen kein Kurs', 'Wetterbedingt finden morgen Samstag, 14. September keine Kurse statt.'),
    ('2024-11-09', 'Fun-Turnier und Welpenabschluss', 'Der Welpenabschluss findet am Samstag, 16. November im Zuge des Welpenkurses statt. Am Samstag, 23. November ab 09:00 startet unser Fun-Turnier. An diesem Tag finden keine Kurs statt. Genauere Informationen findet ihr bei den EVENTS bzw. im KALENDER.'),
    ('2024-11-09', 'Winterpause', 'Nach dem Fun-Turnier am Samstag, 23. November und Rally Obedience am Montag, 25. November, befinden wir uns in der Winterpause.'),
    ('2024-11-24', 'Urkunden Fun-Turnier', 'Da leider gestern auf Grund von technische Problemen das Ausdrucken der Urkunden nicht funktioniert hat, gibt es hier den Link zu den Urkunden.'),
    ('2025-02-03', 'Fotos vom Fun-Turnier', 'Bei den FOTOS findet ihr nun die Bilder von unseren letzten beiden Fun-Turnieren.'),
    ('2025-02-03', 'Neu! Stöbern', 'Unser Kursangebot wurde um Stöbern erweitert. Genauere Informationen hierzu bzw. zu den Kurszeiten und Kosten findet ihr bei KURSE.'),
    ('2025-02-22', 'Beginn Frühjahrskurs', 'Da auf Grund des Umzugs das neue Gelände in St. Margarethen noch nicht komplett fertig ist, starten wir am Samstag, 01. März vorerst nur mit dem Begleithundekurs. Der Welpenkurs und Rally Obedience folgen dann wahrscheinlich ab April. Unsere Welpentrainerin Petra Wolf wird aber schon die Samstage im März vor Ort sein. Somit könnt ihr auch gerne schon vorm Beginn des Welpenkurses vorbeikommen, falls ihr Fragen habt. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter KURSE.'),
    ('2025-03-02', 'Impressionen vom neuen Gelände', 'Gestern starteten wir bei herrlichem Wetter unseren Frühjahrskurs in St. Margarethen. Bei den FOTOS findest du Bilder hierzu. Es ist zwar noch alles etwas provisorisch. Dies sollte sich aber in den nächsten Wochen ändern. Dann werden die Kantine mit WC, sowie die Zäune für den Trainings- und Welpenbereich errichtet.'),
    ('2025-03-28', 'Kein Kurs morgen', 'Auf Grund der schlechten Wettervorhersage finden morgen (29. März) keine Kurse statt. Jedoch gibt es auch gute Nachrichten, ab Montag, 07. April starten wir wieder mit Rally Obedience und ab Mittwoch, 16. April beginnen wir auch mit unserem Stöberkurs.'),
    ('2025-04-04', 'Beginn Welpenkurs', 'Ab morgen (05. April) starten wir nun offiziell mit unserem Welpenkurs. Beginn ist um 15:00.'),
    ('2025-04-25', 'Kein Welpenkurs morgen', 'Morgen (26. April) ist kein Welpenkurs. Die Begleithundekurse finden ganz normal statt.'),
    ('2025-04-25', 'Keine Kurse am 03. Mai', 'Nächsten Samstag (03. Mai) finden keine Kurse statt, da an diesem Tag das Mörbischer Zeitfahren ausgetragen wird. Hier führt ein Teil der Strecke beim Sulzhof vorbei. Somit ist das Zufahren zum Gelände nur schwer bis gar nicht möglich.'),
    ('2025-06-09', 'Keine Kurse am 14. Juni', 'Diesen Samstag (14. Juni) finden keine Kurse statt.'),
    ('2025-06-09', 'Sommerpause', 'Der letzte Kurstag ist am Samstag, 28. Juni. Danach befinden wir uns in der Sommerpause. Der Herbstkurs startet wieder im September.'),
    ('2025-08-29', 'Eröffnungsfest mit Fun-Turnier', 'Wir haben unser offizielles Eröffnungsfest mit Fun-Turnier für Samstag, 04. Oktober geplant. So bald es hier genauere Informationen gibt, findet ihr diese bei den EVENTS.'),
    ('2025-08-29', 'Beginn Herbstkurs', 'Der Herbstkurs startet dieses Jahr am Samstag, 06. September um 15:00 mit den Begleithundekursen. Die weiteren Kurszeiten sind Welpenkurs Mittwoch um 17:00, Stöbern Mittwoch um 18:00 und Rally Obedience Montag um 18:30. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter KURSE bzw. im KALENDER.'),
    ('2025-10-10', 'Fotos vom Eröffnungsfest', 'Bei den FOTOS findet die Bilder von unserem Eröffnungsfest, welches vorigen Samstag bei herrlichem Wetter stattfand. Ein Dank geht an alle Helfer, Teilnehmer und auch an die Kinderfreunde, die das Kinderprogramm gestaltet haben. Bei der Verlosung wurden auch noch nicht alle Preise abgeholt. Also falls ihr noch Steine (Lose) zuhause habt, kommt bitte zu den Kurszeiten vorbei.'),
    ('2025-10-18', 'Kein Kurs am 01. November, Winterpause', 'Am Samstag, 01. November findet auf Grund des Feiertages kein Kurs statt. Der letzte Kurstag ist danach am Samstag, 22. November. Danach befinden wir uns in der Winterpause. Der Frühjahrskurs startet wieder im März.'),
    ('2026-01-17', 'Fotos vom Silvester Dog Walk', 'Bei den FOTOS findet die Bilder von unserem ersten Silvester Dog Walk. Sehr gefreut hat uns, dass trotz eisigem Wind, viele Teilnehmer dabei waren. Gemütlicher war es danach beim Ausklang in der warmen Kantine mit Glühwein und Punsch.'),
    ('2026-02-22', 'Beginn Frühjahrskurs', 'Der Frühjahrskurs startet dieses Jahr am Samstag, 07. März um 15:00 mit den Begleithundekursen. Der Welpenkurs startet am Freitag, 20. März um 16:00, Stöbern am Freitag, 20. März um 17:00 und Rally Obedience am Montag, 09. März um 18:00. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter KURSE bzw. im KALENDER.'),
    ('2026-03-28', 'Keine Kurse am 04. und 18. April', 'Am Samstag, 04. April und Samstag, 18. April finden keine Begleithundekurse statt. Am 04. April auf Grund der Osterfeiertage und am 18. April, da an diesem Tag das Mörbischer Zeitfahren ausgetragen wird. Hier führt ein Teil der Strecke beim Sulzhof vorbei. Somit ist das Zufahren zum Gelände nur schwer bis gar nicht möglich.'),
    ('2026-06-06', 'Keine Kurse, Fun-Turnier', 'Am Samstag, 13. Juni und Samstag, 20. Juni finden keine Begleithundekurse statt. Am 20. Juni ab 09:00 veranstalten wir stattdessen unser Fun-Turnier. Genauere Informationen findet ihr bei den EVENTS bzw. im KALENDER.'),
    ('2026-08-23', 'Fotos vom Fun-Turnier', 'Bei den FOTOS findet ihr nun die Bilder von unseren letzten Fun-Turnier. Ein Dank wieder an alle Teilnehmer, Helfer, Zuschauer und die Kinderfreunde St. Margarethen für das Kinderprogramm.'),
    ('2026-08-23', 'Beginn Herbstkurs', 'Der Herbstkurs startet dieses Jahr am Samstag, 05. September um 14:00 mit den Welpenkurs. Danach folgen wie gewohnt um 15:00 der Begleithundekurs Anfänger und um 16:30 der Begleithundekurs Fortgeschritten. Ein Einstieg ist aber jeder Zeit möglich. Genauere Informationen zu unserem Kursangebot findet ihr unter KURSE bzw. im KALENDER.'),
    ('2026-10-30', 'Theoriekurs für Sachkundenachweis', 'Wir bieten nun auch einen Theoriekurs für den Sachkundenachweis an, welcher seit diesem Jahr für Ersthundebesitzer vor dem Kauf eines Hundes erforderlich ist. Dieser findet jedoch nur bei ausreichender Nachfrage statt. Falls ihr Interesse habt, dann schreibt uns bitte eine E-Mail an mail@og125.at.')
) as v(date, title, content)
where not exists (select 1 from public.news where og = 125);

commit;
